mod rocq_int63 {
//! Trusted runtime for Rocq's 63-bit primitive integers.
//!
//! Every incoming word must be canonical: `0 <= x < 2^63`. This includes words
//! returned by other host replacements. `of_u64` explicitly reduces a host word.
//! No allocation, reference counting, or host-observable state is involved.
//!
//! Word and Ordering results have extraction registrations. Rocq comparison
//! constructors map to Ordering::{Equal, Less, Greater}. Native Rust bool,
//! Carry and division-tuple results below still need extraction ABI mappings.
//! The mulc bridge constructs an ordinary source pair from scalar projections.

use std::cmp::Ordering;

pub type Word = u64;
pub const BITS: u32 = 63;
pub const MASK: Word = (1u64 << BITS) - 1;

#[inline]
pub const fn of_u64(x: u64) -> Word {
    x & MASK
}

/// Interpret bit 62 as the sign bit, without changing the stored word.
#[inline]
const fn signed(x: Word) -> i64 {
    ((x << 1) as i64) >> 1
}

#[inline]
pub const fn lsl(x: Word, shift: Word) -> Word {
    if shift < BITS as Word {
        (x << shift) & MASK
    } else {
        0
    }
}

#[inline]
pub const fn lsr(x: Word, shift: Word) -> Word {
    if shift < BITS as Word {
        x >> shift
    } else {
        0
    }
}

#[inline]
pub const fn asr(x: Word, shift: Word) -> Word {
    // Rocq returns zero for an out-of-range shift, even for negative words.
    if shift < BITS as Word {
        (signed(x) >> shift) as Word & MASK
    } else {
        0
    }
}

#[inline]
pub const fn land(x: Word, y: Word) -> Word {
    x & y
}
#[inline]
pub const fn lor(x: Word, y: Word) -> Word {
    x | y
}
#[inline]
pub const fn lxor(x: Word, y: Word) -> Word {
    x ^ y
}

#[inline]
pub const fn add(x: Word, y: Word) -> Word {
    x.wrapping_add(y) & MASK
}
#[inline]
pub const fn sub(x: Word, y: Word) -> Word {
    x.wrapping_sub(y) & MASK
}
#[inline]
pub const fn mul(x: Word, y: Word) -> Word {
    x.wrapping_mul(y) & MASK
}

#[inline]
pub const fn div(x: Word, y: Word) -> Word {
    if y == 0 {
        0
    } else {
        x / y
    }
}

#[inline]
pub const fn modulo(x: Word, y: Word) -> Word {
    if y == 0 {
        x
    } else {
        x % y
    }
}

#[inline]
pub const fn divs(x: Word, y: Word) -> Word {
    // A signed 63-bit minimum divided by -1 fits in i64; masking restores the
    // 63-bit result, including that overflow case. Division truncates to zero.
    if y == 0 {
        0
    } else {
        signed(x).wrapping_div(signed(y)) as Word & MASK
    }
}

#[inline]
pub const fn mods(x: Word, y: Word) -> Word {
    if y == 0 {
        x
    } else {
        signed(x).wrapping_rem(signed(y)) as Word & MASK
    }
}

#[inline]
pub const fn addmuldiv(shift: Word, x: Word, y: Word) -> Word {
    // Also handles shift=0 (x), shift=63 (y), and shift>63 (zero).
    lor(lsl(x, shift), lsr(y, sub(BITS as Word, shift)))
}

#[inline]
pub const fn head0(x: Word) -> Word {
    (x.leading_zeros() - 1) as Word
}
#[inline]
pub const fn tail0(x: Word) -> Word {
    if x == 0 {
        BITS as Word
    } else {
        x.trailing_zeros() as Word
    }
}

#[inline]
pub const fn eqb(x: Word, y: Word) -> bool {
    x == y
}
#[inline]
pub const fn ltb(x: Word, y: Word) -> bool {
    x < y
}
#[inline]
pub const fn leb(x: Word, y: Word) -> bool {
    x <= y
}
#[inline]
pub const fn ltsb(x: Word, y: Word) -> bool {
    signed(x) < signed(y)
}
#[inline]
pub const fn lesb(x: Word, y: Word) -> bool {
    signed(x) <= signed(y)
}
#[inline]
pub fn compare(x: Word, y: Word) -> Ordering {
    x.cmp(&y)
}
#[inline]
pub fn compares(x: Word, y: Word) -> Ordering {
    signed(x).cmp(&signed(y))
}

/// C1 indicates a carry for addition and a borrow for subtraction.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Carry {
    C0(Word),
    C1(Word),
}

#[inline]
pub const fn addc(x: Word, y: Word) -> Carry {
    let sum = x as u128 + y as u128;
    let word = sum as Word & MASK;
    if sum >> BITS == 0 {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

#[inline]
pub const fn addcarryc(x: Word, y: Word) -> Carry {
    let sum = x as u128 + y as u128 + 1;
    let word = sum as Word & MASK;
    if sum >> BITS == 0 {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

#[inline]
pub const fn subc(x: Word, y: Word) -> Carry {
    let word = sub(x, y);
    if x >= y {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

#[inline]
pub const fn subcarryc(x: Word, y: Word) -> Carry {
    let word = sub(sub(x, y), 1);
    if x > y {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

/// Exact product, high word first, in base 2^63 (not 2^64).
#[inline]
pub const fn mulc(x: Word, y: Word) -> (Word, Word) {
    let product = x as u128 * y as u128;
    ((product >> BITS) as Word, product as Word & MASK)
}

/// Scalar ABI projections; the frontend constructs the ordinary Rocq pair.
#[inline]
pub const fn mulc_high(x: Word, y: Word) -> Word {
    mulc(x, y).0
}
#[inline]
pub const fn mulc_low(x: Word, y: Word) -> Word {
    mulc(x, y).1
}

#[inline]
pub const fn diveucl(x: Word, y: Word) -> (Word, Word) {
    (div(x, y), modulo(x, y))
}

/// Divide a two-word numerator by a word. Rocq returns (0,0) when high>=y,
/// including division by zero; otherwise both quotient and remainder fit.
#[inline]
pub const fn diveucl_21(high: Word, low: Word, y: Word) -> (Word, Word) {
    if high >= y {
        return (0, 0);
    }
    let numerator = ((high as u128) << BITS) | low as u128;
    (
        (numerator / y as u128) as Word,
        (numerator % y as u128) as Word,
    )
}

/// Scalar ABI projections; the frontend constructs the ordinary Rocq pair.
#[inline]
pub const fn diveucl_21_quotient(high: Word, low: Word, y: Word) -> Word {
    diveucl_21(high, low, y).0
}

#[inline]
pub const fn diveucl_21_remainder(high: Word, low: Word, y: Word) -> Word {
    diveucl_21(high, low, y).1
}

}

mod rocq_array {
//! EXPERIMENTAL: writes revoke old array versions instead of copying buffers.
//! Not a refinement of persistent Rocq arrays or the OwnedANF CoW host contract.
//! Only arrays are revoked; ordinary Rc aliasing of other values is unchanged.
#![cfg_attr(not(feature = "unguarded-copy"), forbid(unsafe_code))]
#![deny(unsafe_op_in_unsafe_fn)]

use std::cell::{Ref, RefCell};
use std::rc::Rc;

pub const MAX_LENGTH: u64 = 4_194_303;

#[cold]
#[inline(never)]
fn stale_access(operation: &str, handle: u64, current: u64) -> ! {
    panic!("stale array access ({operation}): handle={handle}, current={current}")
}

#[cold]
#[inline(never)]
fn read_while_borrowed() -> ! {
    panic!("strong array read while mutably borrowed")
}

#[cfg(feature = "unguarded-copy")]
enum ReadFailure {
    Borrowed,
    Stale(u64, u64),
}

/// A checked read scope. References cannot outlive the guard, and writes are
/// rejected until it is dropped. No user callback is run by view accessors.
pub struct ReadView<'a, T> {
    storage: Ref<'a, Storage<T>>,
}

impl<T> ReadView<'_, T> {
    #[inline(always)]
    pub fn get(&self, index: u64) -> &T {
        self.storage
            .elements
            .get(usize::try_from(index).unwrap_or(usize::MAX))
            .unwrap_or(&self.storage.default)
    }

    pub fn length(&self) -> u64 {
        self.storage.elements.len() as u64
    }

    pub fn default(&self) -> &T {
        &self.storage.default
    }
}

/// All aliases of a header share its fixed version. A shared header is never
/// refreshed by a write: the writer receives a new header for the same storage.
pub struct Array<T> {
    version: u64,
    storage: Rc<RefCell<Storage<T>>>,
}

struct Storage<T> {
    version: u64,
    elements: Vec<T>,
    default: T,
}

impl<T> Array<T> {
    pub fn literal(default: T, elements: Vec<T>) -> Self {
        assert!(
            elements.len() as u64 <= MAX_LENGTH,
            "array literal exceeds Rocq maximum"
        );
        Self {
            version: 0,
            storage: Rc::new(RefCell::new(Storage {
                version: 0,
                elements,
                default,
            })),
        }
    }

    #[inline(always)]
    fn read(&self, operation: &str) -> Ref<'_, Storage<T>> {
        let storage = match self.storage.try_borrow() {
            Ok(storage) => storage,
            Err(_) => read_while_borrowed(),
        };
        self.check_version(&storage, operation);
        storage
    }

    #[inline(always)]
    fn check_version(&self, storage: &Storage<T>, operation: &str) {
        if self.version != storage.version {
            stale_access(operation, self.version, storage.version);
        }
    }

    pub fn read_view(&self) -> ReadView<'_, T> {
        ReadView {
            storage: self.read("read_view"),
        }
    }

    /// # Safety
    /// `read` must only access fields/slices and copy values, without mutating
    /// storage or returning a reference into it. While access is active, neither
    /// the operation nor its captures may run user Clone/Drop code, callbacks,
    /// allocation or panic formatting: these could reenter `set`.
    ///
    /// The uncounted borrow does not prevent a subsequent mutable borrow. Rc
    /// excludes cross-thread access, but preventing same-thread reentrancy is
    /// the caller's responsibility. Keep all failure formatting in `finish_copy`,
    /// after this function has returned and the storage reference has ended.
    #[cfg(feature = "unguarded-copy")]
    #[inline(always)]
    unsafe fn copy_storage<R: Copy>(
        &self,
        read: impl FnOnce(&Storage<T>) -> R,
    ) -> Result<R, ReadFailure> {
        // SAFETY: Rc makes this single-threaded. The standard-library check
        // rejects an active mutable borrow. The private callers execute no
        // user code or mutation before the reference ends, return no storage
        // reference, and copy without invoking T::clone. Existing counted host
        // guards still block writes, but this uncounted reference itself does
        // not: its lifetime must contain no opportunity to reenter set. The
        // version check detects stale handles; it cannot protect a live &Storage
        // from mutation. Current callers satisfy the contract above.
        let storage = match unsafe { self.storage.try_borrow_unguarded() } {
            Ok(storage) => storage,
            Err(_) => return Err(ReadFailure::Borrowed),
        };
        if self.version != storage.version {
            return Err(ReadFailure::Stale(self.version, storage.version));
        }
        Ok(read(storage))
    }

    #[cfg(feature = "unguarded-copy")]
    #[inline(always)]
    fn finish_copy<R>(result: Result<R, ReadFailure>, operation: &str) -> R {
        match result {
            Ok(value) => value,
            Err(ReadFailure::Borrowed) => read_while_borrowed(),
            Err(ReadFailure::Stale(handle, current)) => stale_access(operation, handle, current),
        }
    }

    #[inline(always)]
    pub fn get_copy(&self, index: u64) -> T
    where
        T: Copy,
    {
        #[cfg(feature = "unguarded-copy")]
        {
            // SAFETY: only copy an existing element/default; no Clone, user
            // callback or escaping borrow. Error formatting is outside access.
            let result = unsafe {
                self.copy_storage(|s| {
                    *s.elements
                        .get(usize::try_from(index).unwrap_or(usize::MAX))
                        .unwrap_or(&s.default)
                })
            };
            Self::finish_copy(result, "get_copy")
        }
        #[cfg(not(feature = "unguarded-copy"))]
        {
            *self.get(index)
        }
    }

    pub fn default_copy(&self) -> T
    where
        T: Copy,
    {
        #[cfg(feature = "unguarded-copy")]
        {
            // SAFETY: Copy performs no callback; the value does not borrow its slot.
            let result = unsafe { self.copy_storage(|s| s.default) };
            Self::finish_copy(result, "default_copy")
        }
        #[cfg(not(feature = "unguarded-copy"))]
        {
            *self.default()
        }
    }

    /// Host-only guarded access. Holding the guard makes writes panic *before*
    /// mutation. Generated get calls instead clone the value and release it.
    #[inline(always)]
    pub fn get(&self, index: u64) -> Ref<'_, T> {
        Ref::map(self.read("get"), |s| {
            s.elements
                .get(usize::try_from(index).unwrap_or(usize::MAX))
                .unwrap_or(&s.default)
        })
    }

    pub fn default(&self) -> Ref<'_, T> {
        Ref::map(self.read("default"), |s| &s.default)
    }

    pub fn length(&self) -> u64 {
        #[cfg(feature = "unguarded-copy")]
        {
            // SAFETY: read scalar Vec metadata only, without invoking element code.
            let result = unsafe { self.copy_storage(|s| s.elements.len() as u64) };
            Self::finish_copy(result, "length")
        }
        #[cfg(not(feature = "unguarded-copy"))]
        {
            self.read("length").elements.len() as u64
        }
    }
}

pub fn make<T: Clone>(length: u64, default: T) -> Rc<Array<T>> {
    Rc::new(Array::literal(
        default.clone(),
        vec![default; length.min(MAX_LENGTH) as usize],
    ))
}

// Expose the guard's lifetime and cleanup to the monomorphized caller. The
// version/bounds/borrow checks remain; this does not assume unique array use.
#[inline(always)]
pub fn set<T>(mut array: Rc<Array<T>>, index: u64, value: T) -> Rc<Array<T>> {
    let mut storage = array
        .storage
        .try_borrow_mut()
        .expect("strong array write while borrowed");
    array.check_version(&storage, "set");
    let index = usize::try_from(index)
        .ok()
        .filter(|&i| i < storage.elements.len());
    let Some(index) = index else {
        drop(storage);
        return array;
    };
    let version = storage
        .version
        .checked_add(1)
        .expect("strong array version overflow");
    // Revoke first: if dropping the overwritten host value panics, no old
    // version can subsequently observe the partially completed write as valid.
    storage.version = version;
    storage.elements[index] = value;
    drop(storage);
    if let Some(header) = Rc::get_mut(&mut array) {
        header.version = version;
        array
    } else {
        Rc::new(Array {
            version,
            storage: Rc::clone(&array.storage),
        })
    }
}

#[inline(always)]
pub fn get<T: Clone>(array: &Rc<Array<T>>, index: u64) -> T {
    T::clone(&array.get(index))
}

#[inline(always)]
pub fn get_copy<T: Copy>(array: &Rc<Array<T>>, index: u64) -> T {
    array.get_copy(index)
}

pub fn length<T>(array: &Rc<Array<T>>) -> u64 {
    array.length()
}

pub fn default<T: Clone>(array: &Rc<Array<T>>) -> T {
    T::clone(&array.default())
}

/// Independent *shallow* buffer copy, like Marray.copy. Nested array/other Rc
/// elements remain aliases; this does not recursively snapshot their payloads.
pub fn copy<T: Clone>(array: &Rc<Array<T>>) -> Rc<Array<T>> {
    let storage = array.read("copy");
    Rc::new(Array::literal(
        storage.default.clone(),
        storage.elements.clone(),
    ))
}


}

mod rocq_bigint {
//! Trusted, standard-library-only bigint hosts. Ported from kattis/tools/bigint.ml.
//! Normalized sign-magnitude, little-endian base-2^31 limbs; immutable Rc handles.
//! Registered constructor tags and field decoders support mapped Rocq matches.
// SPDX-License-Identifier: BSD-3-Clause
use std::{cmp::Ordering, fmt, rc::Rc, str::FromStr};

const BITS: usize = 31;
const BASE: u64 = 1 << BITS;
const MASK: u64 = BASE - 1;
pub type Int = Rc<BigInt>;

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct BigInt {
    sign: i8,
    mag: Vec<u32>,
}

fn trim(mut a: Vec<u32>) -> Vec<u32> {
    while a.last() == Some(&0) {
        a.pop();
    }
    a
}
fn mk(sign: i8, mag: Vec<u32>) -> Int {
    let mag = trim(mag);
    Rc::new(BigInt {
        sign: if mag.is_empty() { 0 } else { sign },
        mag,
    })
}
pub fn zero() -> Int {
    mk(0, vec![])
}
pub fn one() -> Int {
    mk(1, vec![1])
}
pub fn identity(x: Int) -> Int {
    x
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PositiveTag {
    Odd,
    Even,
    One,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum NaturalTag {
    Zero,
    Positive,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IntegerTag {
    Zero,
    Positive,
    Negative,
}

/// One-layer observations of the Rocq constructors, not of the limb layout.
pub fn positive_tag(x: Int) -> PositiveTag {
    assert!(x.sign > 0, "invalid positive representation");
    if x.mag == [1] {
        PositiveTag::One
    } else if x.mag[0] & 1 == 0 {
        PositiveTag::Even
    } else {
        PositiveTag::Odd
    }
}
pub fn positive_tail(x: Int) -> Int {
    assert!(x.sign > 0, "invalid positive representation");
    if x.mag == [1] {
        x
    } else {
        mk(1, ushr(&x.mag, 1))
    }
}
pub fn natural_tag(x: Int) -> NaturalTag {
    assert!(x.sign >= 0, "invalid natural representation");
    if x.sign == 0 {
        NaturalTag::Zero
    } else {
        NaturalTag::Positive
    }
}
pub fn natural_payload(x: Int) -> Int {
    assert!(x.sign >= 0, "invalid natural representation");
    if x.sign == 0 {
        one()
    } else {
        x
    }
}
pub fn integer_tag(x: Int) -> IntegerTag {
    match x.sign {
        0 => IntegerTag::Zero,
        1 => IntegerTag::Positive,
        _ => IntegerTag::Negative,
    }
}
pub fn integer_magnitude(x: Int) -> Int {
    match x.sign {
        0 => one(),
        1 => x,
        _ => abs(x),
    }
}
fn ucmp(a: &[u32], b: &[u32]) -> Ordering {
    a.len()
        .cmp(&b.len())
        .then_with(|| a.iter().rev().cmp(b.iter().rev()))
}
fn uadd(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut r = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry = 0;
    for i in 0..a.len().max(b.len()) {
        let t =
            a.get(i).copied().unwrap_or(0) as u64 + b.get(i).copied().unwrap_or(0) as u64 + carry;
        r.push((t & MASK) as u32);
        carry = t >> BITS;
    }
    if carry != 0 {
        r.push(carry as u32);
    }
    r
}
fn usub(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut r = Vec::with_capacity(a.len());
    let mut borrow = 0i64;
    for (i, &x) in a.iter().enumerate() {
        let t = x as i64 - b.get(i).copied().unwrap_or(0) as i64 - borrow;
        r.push((t & MASK as i64) as u32);
        borrow = i64::from(t < 0);
    }
    assert_eq!(borrow, 0);
    trim(r)
}
fn add_into(r: &mut [u32], off: usize, x: &[u32]) {
    let (mut i, mut carry) = (0, 0u64);
    while i < x.len() || carry != 0 {
        let t = r[off + i] as u64 + x.get(i).copied().unwrap_or(0) as u64 + carry;
        r[off + i] = (t & MASK) as u32;
        carry = t >> BITS;
        i += 1;
    }
}
fn umul(a: &[u32], b: &[u32]) -> Vec<u32> {
    if a.is_empty() || b.is_empty() {
        return vec![];
    }
    if a.len().min(b.len()) < 40 {
        let mut r = vec![0; a.len() + b.len()];
        for (i, &x) in a.iter().enumerate() {
            let mut carry = 0u64;
            for (j, &y) in b.iter().enumerate() {
                let t = x as u64 * y as u64 + r[i + j] as u64 + carry;
                r[i + j] = (t & MASK) as u32;
                carry = t >> BITS;
            }
            r[i + b.len()] = carry as u32;
        }
        return trim(r);
    }
    let m = a.len().max(b.len()) / 2;
    let mut r = vec![0; a.len() + b.len() + 1];
    if a.len().min(b.len()) <= m {
        let (a, b) = if a.len() >= b.len() { (a, b) } else { (b, a) };
        add_into(&mut r, 0, &umul(&trim(a[..m].to_vec()), b));
        add_into(&mut r, m, &umul(&a[m..], b));
    } else {
        let (a0, b0) = (trim(a[..m].to_vec()), trim(b[..m].to_vec()));
        let (a1, b1) = (&a[m..], &b[m..]);
        let (z0, z2) = (umul(&a0, &b0), umul(a1, b1));
        let z1 = usub(&usub(&umul(&uadd(&a0, a1), &uadd(&b0, b1)), &z0), &z2);
        add_into(&mut r, 0, &z0);
        add_into(&mut r, m, &z1);
        add_into(&mut r, 2 * m, &z2);
    }
    trim(r)
}
fn umul_small(a: &[u32], d: u64, mut carry: u64) -> Vec<u32> {
    let mut r = Vec::with_capacity(a.len() + 1);
    for &x in a {
        let t = x as u64 * d + carry;
        r.push((t & MASK) as u32);
        carry = t >> BITS;
    }
    if carry != 0 {
        r.push(carry as u32);
    }
    r
}
fn udiv_small(a: &[u32], d: u64) -> (Vec<u32>, u64) {
    let mut q = vec![0; a.len()];
    let mut rem = 0;
    for i in (0..a.len()).rev() {
        let t = (rem << BITS) | a[i] as u64;
        q[i] = (t / d) as u32;
        rem = t % d;
    }
    (trim(q), rem)
}
fn ushl(a: &[u32], n: usize) -> Vec<u32> {
    if a.is_empty() {
        return vec![];
    }
    let (limbs, bits) = (n / BITS, n % BITS);
    let mut r = vec![
        0;
        a.len()
            .checked_add(limbs)
            .and_then(|x| x.checked_add(1))
            .expect("bigint shift size overflow")
    ];
    for (i, &x) in a.iter().enumerate() {
        let w = (x as u64) << bits;
        r[i + limbs] |= (w & MASK) as u32;
        r[i + limbs + 1] |= (w >> BITS) as u32;
    }
    trim(r)
}
fn ushr(a: &[u32], n: usize) -> Vec<u32> {
    let (limbs, bits) = (n / BITS, n % BITS);
    if limbs >= a.len() {
        return vec![];
    }
    trim(
        (limbs..a.len())
            .map(|i| {
                let hi = if bits != 0 {
                    (a.get(i + 1).copied().unwrap_or(0) as u64) << (BITS - bits)
                } else {
                    0
                };
                (((a[i] as u64) >> bits | hi) & MASK) as u32
            })
            .collect(),
    )
}
// Knuth Algorithm D. Intermediate products fit in u64 (at most 62 bits).
fn udivmod(a: &[u32], b: &[u32]) -> (Vec<u32>, Vec<u32>) {
    assert!(!b.is_empty(), "bigint internal division by zero");
    if ucmp(a, b) == Ordering::Less {
        return (vec![], a.to_vec());
    }
    if b.len() == 1 {
        let (q, r) = udiv_small(a, b[0] as u64);
        return (q, if r == 0 { vec![] } else { vec![r as u32] });
    }
    let (la, lb) = (a.len(), b.len());
    let s = b[lb - 1].leading_zeros() as usize - 1;
    let v = ushl(b, s);
    let mut u = ushl(a, s);
    u.resize(la + 1, 0);
    let (vtop, vnext) = (v[lb - 1] as u64, v[lb - 2] as u64);
    let mut q = vec![0; la - lb + 1];
    for j in (0..=la - lb).rev() {
        let num = ((u[j + lb] as u64) << BITS) | u[j + lb - 1] as u64;
        let (mut qh, mut rh) = (num / vtop, num % vtop);
        while rh < BASE && (qh >= BASE || qh * vnext > (rh << BITS) | u[j + lb - 2] as u64) {
            qh -= 1;
            rh += vtop;
        }
        let (mut carry, mut borrow) = (0u64, 0i64);
        for i in 0..lb {
            let p = qh * v[i] as u64 + carry;
            carry = p >> BITS;
            let d = u[i + j] as i64 - (p & MASK) as i64 - borrow;
            u[i + j] = (d & MASK as i64) as u32;
            borrow = i64::from(d < 0);
        }
        let d = u[j + lb] as i64 - carry as i64 - borrow;
        u[j + lb] = (d & MASK as i64) as u32;
        if d < 0 {
            q[j] = (qh - 1) as u32;
            let mut c = 0u64;
            for i in 0..lb {
                let t = u[i + j] as u64 + v[i] as u64 + c;
                u[i + j] = (t & MASK) as u32;
                c = t >> BITS;
            }
            u[j + lb] = ((u[j + lb] as u64 + c) & MASK) as u32;
        } else {
            q[j] = qh as u32;
        }
    }
    (trim(q), ushr(&trim(u[..lb].to_vec()), s))
}

pub fn compare(x: Int, y: Int) -> Ordering {
    x.sign.cmp(&y.sign).then_with(|| {
        if x.sign < 0 {
            ucmp(&y.mag, &x.mag)
        } else {
            ucmp(&x.mag, &y.mag)
        }
    })
}
pub fn equal(x: Int, y: Int) -> bool {
    x == y
}
pub fn lt(x: Int, y: Int) -> bool {
    compare(x, y) == Ordering::Less
}
pub fn le(x: Int, y: Int) -> bool {
    compare(x, y) != Ordering::Greater
}
pub fn gt(x: Int, y: Int) -> bool {
    lt(y, x)
}
pub fn ge(x: Int, y: Int) -> bool {
    le(y, x)
}
pub fn min(x: Int, y: Int) -> Int {
    if le(x.clone(), y.clone()) {
        x
    } else {
        y
    }
}
pub fn max(x: Int, y: Int) -> Int {
    if ge(x.clone(), y.clone()) {
        x
    } else {
        y
    }
}
pub fn compare_cont(c: Ordering, x: Int, y: Int) -> Ordering {
    let r = compare(x, y);
    if r == Ordering::Equal {
        c
    } else {
        r
    }
}
pub fn neg(x: Int) -> Int {
    mk(-x.sign, x.mag.clone())
}
pub fn abs(x: Int) -> Int {
    mk(1, x.mag.clone())
}
pub fn add(x: Int, y: Int) -> Int {
    if x.sign == 0 {
        return y;
    }
    if y.sign == 0 {
        return x;
    }
    if x.sign == y.sign {
        return mk(x.sign, uadd(&x.mag, &y.mag));
    }
    match ucmp(&x.mag, &y.mag) {
        Ordering::Equal => zero(),
        Ordering::Greater => mk(x.sign, usub(&x.mag, &y.mag)),
        Ordering::Less => mk(y.sign, usub(&y.mag, &x.mag)),
    }
}
pub fn sub(x: Int, y: Int) -> Int {
    // Subtract magnitudes directly: neg(y) would allocate a temporary bigint
    // and copy its digits even though only its sign is needed here.
    if y.sign == 0 {
        return x;
    }
    if x.sign == 0 {
        return neg(y);
    }
    if x.sign != y.sign {
        return mk(x.sign, uadd(&x.mag, &y.mag));
    }
    match ucmp(&x.mag, &y.mag) {
        Ordering::Equal => zero(),
        Ordering::Greater => mk(x.sign, usub(&x.mag, &y.mag)),
        Ordering::Less => mk(-x.sign, usub(&y.mag, &x.mag)),
    }
}
pub fn succ(x: Int) -> Int {
    add(x, one())
}
pub fn pred(x: Int) -> Int {
    sub(x, one())
}
pub fn pos_pred(x: Int) -> Int {
    max(one(), pred(x))
}
pub fn pos_sub(x: Int, y: Int) -> Int {
    max(one(), sub(x, y))
}
pub fn nonnegative(x: Int) -> Int {
    if x.sign < 0 {
        zero()
    } else {
        x
    }
}
/// Rocq's Z.to_pos preserves positive inputs and maps zero/negatives to one.
pub fn to_positive(x: Int) -> Int {
    if x.sign > 0 {
        x
    } else {
        one()
    }
}
pub fn n_pred(x: Int) -> Int {
    nonnegative(pred(x))
}
pub fn n_sub(x: Int, y: Int) -> Int {
    nonnegative(sub(x, y))
}
pub fn mul(x: Int, y: Int) -> Int {
    mk(x.sign * y.sign, umul(&x.mag, &y.mag))
}
pub fn of_uint63(x: u64) -> Int {
    let x = x & ((1u64 << 63) - 1);
    mk(
        1,
        vec![
            (x & MASK) as u32,
            ((x >> 31) & MASK) as u32,
            (x >> 62) as u32,
        ],
    )
}
pub fn to_uint63(x: Int) -> u64 {
    let get = |i| x.mag.get(i).copied().unwrap_or(0) as u64;
    let w = get(0) | (get(1) << 31) | ((get(2) & 1) << 62);
    (if x.sign < 0 { w.wrapping_neg() } else { w }) & ((1u64 << 63) - 1)
}
// Rocq division is total: division by zero returns (0,x).
pub fn tdiv_rem(x: Int, y: Int) -> (Int, Int) {
    if y.sign == 0 {
        return (zero(), x);
    }
    let (q, r) = udivmod(&x.mag, &y.mag);
    (mk(x.sign * y.sign, q), mk(x.sign, r))
}
pub fn fdiv_rem(x: Int, y: Int) -> (Int, Int) {
    let (q, r) = tdiv_rem(x, y.clone());
    if r.sign != 0 && y.sign != 0 && r.sign != y.sign {
        (pred(q), add(r, y))
    } else {
        (q, r)
    }
}
pub fn div(x: Int, y: Int) -> Int {
    fdiv_rem(x, y).0
}
pub fn modulo(x: Int, y: Int) -> Int {
    fdiv_rem(x, y).1
}
pub fn quot(x: Int, y: Int) -> Int {
    tdiv_rem(x, y).0
}
pub fn rem(x: Int, y: Int) -> Int {
    tdiv_rem(x, y).1
}
pub fn gcd(x: Int, y: Int) -> Int {
    let (mut a, mut b) = (x.mag.clone(), y.mag.clone());
    while !b.is_empty() {
        let r = udivmod(&a, &b).1;
        a = b;
        b = r;
    }
    mk(1, a)
}
fn numbits(x: &BigInt) -> usize {
    x.mag.last().map_or(0, |&v| {
        (x.mag.len() - 1) * BITS + (32 - v.leading_zeros()) as usize
    })
}
fn index(x: &BigInt) -> Option<usize> {
    if x.sign < 0 || numbits(x) > usize::BITS as usize {
        return None;
    }
    Some(
        x.mag
            .iter()
            .rev()
            .fold(0u128, |a, &v| (a << BITS) | v as u128) as usize,
    )
}
pub fn pow(x: Int, y: Int) -> Int {
    if y.sign < 0 {
        return zero();
    }
    let mut n = index(&y).expect("bigint exponent exceeds address space");
    let (mut acc, mut b) = (one(), x);
    while n != 0 {
        if n & 1 != 0 {
            acc = mul(acc, b.clone());
        }
        n >>= 1;
        if n != 0 {
            b = mul(b.clone(), b);
        }
    }
    acc
}
pub fn sqrt(x: Int) -> Int {
    if x.sign <= 0 {
        return zero();
    }
    let mut r = ushl(&[1], numbits(&x).div_ceil(2));
    loop {
        let next = ushr(&uadd(&r, &udivmod(&x.mag, &r).0), 1);
        if ucmp(&next, &r) != Ordering::Less {
            return mk(1, r);
        }
        r = next;
    }
}
pub fn log2(x: Int) -> Int {
    if x.sign <= 0 {
        zero()
    } else {
        of_uint63((numbits(&x) - 1) as u64)
    }
}
pub fn lognot(x: Int) -> Int {
    pred(neg(x))
}
fn shr(x: Int, n: usize) -> Int {
    if x.sign >= 0 {
        mk(1, ushr(&x.mag, n))
    } else {
        lognot(mk(1, ushr(&lognot(x).mag, n)))
    }
}
pub fn shiftl(x: Int, y: Int) -> Int {
    if y.sign < 0 {
        return shiftr(x, neg(y));
    }
    if x.sign == 0 {
        return x;
    }
    mk(
        x.sign,
        ushl(
            &x.mag,
            index(&y).expect("bigint left shift exceeds address space"),
        ),
    )
}
pub fn shiftr(x: Int, y: Int) -> Int {
    if y.sign < 0 {
        return shiftl(x, neg(y));
    }
    // Huge right shifts have a finite answer; never allocate or truncate the count.
    match index(&y) {
        Some(n) => shr(x, n),
        None => {
            if x.sign < 0 {
                neg(one())
            } else {
                zero()
            }
        }
    }
}
pub fn twice(x: Int) -> Int {
    mk(x.sign, ushl(&x.mag, 1))
}
pub fn twice_plus_one(x: Int) -> Int {
    succ(twice(x))
}
pub fn odd(x: Int) -> bool {
    x.mag.first().copied().unwrap_or(0) & 1 != 0
}
pub fn even(x: Int) -> bool {
    !odd(x)
}
pub fn testbit(x: Int, n: Int) -> bool {
    if n.sign < 0 {
        return false;
    }
    let negative = x.sign < 0;
    let a = if negative { lognot(x) } else { x };
    let bit = index(&n)
        .and_then(|k| a.mag.get(k / BITS).map(|v| (v >> (k % BITS)) & 1 != 0))
        .unwrap_or(false);
    bit ^ negative
}
fn ubits(a: &[u32], b: &[u32], op: fn(u32, u32) -> u32) -> Vec<u32> {
    trim(
        (0..a.len().max(b.len()))
            .map(|i| {
                op(
                    a.get(i).copied().unwrap_or(0),
                    b.get(i).copied().unwrap_or(0),
                ) & MASK as u32
            })
            .collect(),
    )
}
pub fn logand(x: Int, y: Int) -> Int {
    match (x.sign < 0, y.sign < 0) {
        (false, false) => mk(1, ubits(&x.mag, &y.mag, |a, b| a & b)),
        (false, true) => mk(1, ubits(&x.mag, &lognot(y).mag, |a, b| a & !b)),
        (true, false) => logand(y, x),
        (true, true) => lognot(mk(1, ubits(&lognot(x).mag, &lognot(y).mag, |a, b| a | b))),
    }
}
pub fn logor(x: Int, y: Int) -> Int {
    match (x.sign < 0, y.sign < 0) {
        (false, false) => mk(1, ubits(&x.mag, &y.mag, |a, b| a | b)),
        (false, true) => lognot(mk(1, ubits(&lognot(y).mag, &x.mag, |a, b| a & !b))),
        (true, false) => logor(y, x),
        (true, true) => lognot(mk(1, ubits(&lognot(x).mag, &lognot(y).mag, |a, b| a & b))),
    }
}
pub fn logxor(x: Int, y: Int) -> Int {
    let (nx, ny) = (x.sign < 0, y.sign < 0);
    let (x, y) = (
        if nx { lognot(x) } else { x },
        if ny { lognot(y) } else { y },
    );
    let r = mk(1, ubits(&x.mag, &y.mag, |a, b| a ^ b));
    if nx ^ ny {
        lognot(r)
    } else {
        r
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseBigIntError;
impl FromStr for BigInt {
    type Err = ParseBigIntError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let (sign, s) = if let Some(s) = s.strip_prefix('-') {
            (-1, s)
        } else {
            (1, s.strip_prefix('+').unwrap_or(s))
        };
        if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
            return Err(ParseBigIntError);
        }
        let mut mag = vec![];
        for part in s.as_bytes().chunks(9) {
            let (mut v, mut p) = (0, 1);
            for &c in part {
                v = v * 10 + (c - b'0') as u64;
                p *= 10;
            }
            mag = umul_small(&mag, p, v);
        }
        let mag = trim(mag);
        Ok(BigInt {
            sign: if mag.is_empty() { 0 } else { sign },
            mag,
        })
    }
}
impl fmt::Display for BigInt {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.sign == 0 {
            return f.write_str("0");
        }
        let mut parts = vec![];
        let mut mag = self.mag.clone();
        while !mag.is_empty() {
            let (q, r) = udiv_small(&mag, 1_000_000_000);
            parts.push(r);
            mag = q;
        }
        if self.sign < 0 {
            f.write_str("-")?;
        }
        write!(f, "{}", parts.pop().unwrap())?;
        for p in parts.iter().rev() {
            write!(f, "{p:09}")?;
        }
        Ok(())
    }
}
pub fn of_string(s: &str) -> Result<Int, ParseBigIntError> {
    s.parse().map(Rc::new)
}

}

mod rocq_float64 {
//! Trusted adapter for Rocq primitive binary64 operations. See README.md.
#![allow(dead_code)]

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FloatComparison { Equal, Less, Greater, NotComparable }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FloatClass {
    PNormal, NNormal, PSubn, NSubn, PZero, NZero, PInf, NInf, NaN,
}

pub fn add(x: f64, y: f64) -> f64 { x + y }
pub fn sub(x: f64, y: f64) -> f64 { x - y }
pub fn mul(x: f64, y: f64) -> f64 { x * y }
pub fn div(x: f64, y: f64) -> f64 { x / y }
pub fn sqrt(x: f64) -> f64 { x.sqrt() }
pub fn abs(x: f64) -> f64 { x.abs() }
pub fn opp(x: f64) -> f64 { -x }
pub fn eqb(x: f64, y: f64) -> bool { x == y }
pub fn ltb(x: f64, y: f64) -> bool { x < y }
pub fn leb(x: f64, y: f64) -> bool { x <= y }

/// Rocq has one abstract NaN, but distinguishes the two zeros for Leibniz equality.
pub fn leibniz_eqb(x: f64, y: f64) -> bool {
    x.to_bits() == y.to_bits() || (x.is_nan() && y.is_nan())
}

pub fn compare(x: f64, y: f64) -> FloatComparison {
    use std::cmp::Ordering;
    match x.partial_cmp(&y) {
        Some(Ordering::Equal) => FloatComparison::Equal,
        Some(Ordering::Less) => FloatComparison::Less,
        Some(Ordering::Greater) => FloatComparison::Greater,
        None => FloatComparison::NotComparable,
    }
}

pub fn classify(x: f64) -> FloatClass {
    use std::num::FpCategory;
    use FloatClass::*;
    match (x.classify(), x.is_sign_negative()) {
        (FpCategory::Nan, _) => NaN,
        (FpCategory::Normal, false) => PNormal,
        (FpCategory::Normal, true) => NNormal,
        (FpCategory::Subnormal, false) => PSubn,
        (FpCategory::Subnormal, true) => NSubn,
        (FpCategory::Zero, false) => PZero,
        (FpCategory::Zero, true) => NZero,
        (FpCategory::Infinite, false) => PInf,
        (FpCategory::Infinite, true) => NInf,
    }
}

/// Input must be a canonical unsigned int63 word, as in rocq_int63.
pub fn of_uint63(x: u64) -> f64 { x as f64 }

pub fn normfr_mantissa(x: f64) -> u64 {
    let x = x.abs();
    if (0.5..1.0).contains(&x) {
        (x.to_bits() & ((1u64 << 52) - 1)) | (1u64 << 52)
    } else {
        0
    }
}

/// Finite, nonzero binary64 as sign, 53-bit significand and unbiased exponent.
fn normalized(x: f64) -> Option<(u64, u64, i32)> {
    let bits = x.to_bits();
    let sign = bits & (1u64 << 63);
    let exponent = ((bits >> 52) & 0x7ff) as i32;
    let fraction = bits & ((1u64 << 52) - 1);
    if exponent == 0x7ff || (exponent == 0 && fraction == 0) { return None; }
    if exponent == 0 {
        let shift = fraction.leading_zeros() - 11;
        Some((sign, fraction << shift, -1022 - shift as i32))
    } else {
        Some((sign, fraction | (1u64 << 52), exponent - 1023))
    }
}

/// Rocq frexp: exponent shifted by 2101; special values have exponent zero.
pub fn frshiftexp(x: f64) -> (f64, u64) {
    match normalized(x) {
        None => (x, 0),
        Some((sign, mantissa, exponent)) =>
            (f64::from_bits(sign | (1022u64 << 52) | (mantissa & ((1u64 << 52) - 1))),
             (exponent + 2102) as u64),
    }
}

// Scalar projection ABI used by the frontend's pair-construction bridge.
pub fn frshiftexp_fraction(x: f64) -> f64 { frshiftexp(x).0 }
pub fn frshiftexp_exponent(x: f64) -> u64 { frshiftexp(x).1 }

/// x * 2^(min(e, 4202) - 2101), rounded once, ties to even.
/// Integer bit manipulation avoids powi overflow and double rounding on underflow.
pub fn ldshiftexp(x: f64, e: u64) -> f64 {
    let Some((sign, mantissa, exponent)) = normalized(x) else { return x; };
    let exponent = exponent + e.min(4202) as i32 - 2101;
    let magnitude = if exponent > 1023 {
        0x7ffu64 << 52
    } else if exponent >= -1022 {
        ((exponent + 1023) as u64) << 52 | (mantissa & ((1u64 << 52) - 1))
    } else {
        let shift = (-1022 - exponent) as u32;
        if shift > 53 { 0 } else {
            let integral = mantissa >> shift;
            let remainder = mantissa & ((1u64 << shift) - 1);
            let halfway = 1u64 << (shift - 1);
            integral + u64::from(remainder > halfway || (remainder == halfway && integral & 1 != 0))
        }
    };
    f64::from_bits(sign | magnitude)
}

pub fn next_up(x: f64) -> f64 {
    if x.is_nan() || x == f64::INFINITY { return x; }
    if x == 0.0 { return f64::from_bits(1); }
    f64::from_bits(if x > 0.0 { x.to_bits() + 1 } else { x.to_bits() - 1 })
}

pub fn next_down(x: f64) -> f64 {
    if x.is_nan() || x == f64::NEG_INFINITY { return x; }
    if x == 0.0 { return f64::from_bits((1u64 << 63) | 1); }
    f64::from_bits(if x > 0.0 { x.to_bits() - 1 } else { x.to_bits() + 1 })
}

}

mod rocq_string {
//! Immutable byte strings; owning values use Rc<RocqString>, never UTF-8 str.
use std::rc::Rc;
use std::cmp::Ordering;

/// Rocq's portable primitive-string limit (also used on 64-bit hosts).
pub const MAX_LENGTH: usize = 16_777_211;

#[derive(Debug)]
pub struct RocqString {
    bytes: Box<[u8]>,
}

impl RocqString {
    pub fn from_bytes(bytes: Vec<u8>) -> Self {
        assert!(
            bytes.len() <= MAX_LENGTH,
            "Rocq primitive string exceeds max_length"
        );
        Self {
            bytes: bytes.into_boxed_slice(),
        }
    }
}

pub fn length(s: &Rc<RocqString>) -> u64 {
    s.bytes.len() as u64
}

pub fn get(s: &Rc<RocqString>, index: u64) -> u64 {
    usize::try_from(index)
        .ok()
        .and_then(|i| s.bytes.get(i))
        .copied()
        .unwrap_or(0) as u64
}

/// Rocq clamps the length and takes the low eight bits of the character.
pub fn make(length: u64, byte: u64) -> Rc<RocqString> {
    let length = length.min(MAX_LENGTH as u64) as usize;
    Rc::new(RocqString::from_bytes(vec![byte as u8; length]))
}

/// Unsigned lexicographic byte ordering, including embedded NULs.
pub fn compare(left: &Rc<RocqString>, right: &Rc<RocqString>) -> Ordering {
    left.bytes.cmp(&right.bytes)
}

/// Preserve all of the left string and the longest representable right prefix.
pub fn cat(left: &Rc<RocqString>, right: &Rc<RocqString>) -> Rc<RocqString> {
    let extra = right.bytes.len().min(MAX_LENGTH - left.bytes.len());
    let mut bytes = Vec::with_capacity(left.bytes.len() + extra);
    bytes.extend_from_slice(&left.bytes);
    bytes.extend_from_slice(&right.bytes[..extra]);
    Rc::new(RocqString::from_bytes(bytes))
}


}

